sect2.example:
    Estendendo Exception


<?php
class CustomException extends Exception
{
    // Redefine o construtor para que a mensagem seja obrigatória
    public function __construct($message, $code = 0, ?Throwable $previous = null) {
        // algum código

        // Garanta que tudo seja atribuído corretamente
        parent::__construct($message, $code, $previous);
    }

    // Representação textual personalizada do objeto
    public function __toString() {
        return __CLASS__ . ": [{$this->code}]: {$this->message}\n";
    }

    public function customFunction() {
        echo "A custom function for this type of exception\n";
    }
}

try {
    throw new CustomException("Something happened", 5);
} catch (CustomException $e) {
    echo "Caught custom exception\n", $e;
    $e->customFunction();
}


    &example.outputs;


Caught custom exception
CustomException: [5]: Something happened
A custom function for this type of exception

